stock_scanner.py.get_json:
def get_json(url, timeout=25):
    req = urllib.request.Request(url, headers=HEADERS)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"HTTP {exc.code} for {url}: {body[:500]}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Request failed for {url}: {exc}") from exc

stock_scanner.py.pct_change:
def pct_change(new, old):
    if new is None or old in (None, 0):
        return None
    return (new / old - 1.0) * 100.0

stock_scanner.py.scale:
def scale(value, start, end, points):
    if value is None or end == start:
        return 0.0
    return clamp((value - start) / (end - start)) * points

stock_scanner.py.fmt:
def fmt(value, digits=2):
    if value is None:
        return "-"
    return f"{value:.{digits}f}"

stock_scanner.py.shorten:
def shorten(text, limit=150):
    text = " ".join(str(text or "").split())
    if len(text) <= limit:
        return text
    return text[: limit - 3] + "..."

stock_scanner.py.parse_timestamp:
def parse_timestamp(value):
    if not value:
        return None
    try:
        text = str(value).strip()
        try:
            numeric = float(text)
            if numeric > 10_000_000_000:
                numeric /= 1000.0
            if numeric > 1_000_000_000:
                return datetime.fromtimestamp(
                    numeric,
                    tz=timezone.utc,
                )
        except (TypeError, ValueError, OverflowError):
            pass
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    except (ValueError, TypeError):
        return None

stock_scanner.py.likely_common_stock:
def likely_common_stock(symbol):
    s = symbol.upper().strip()
    if not s or len(s) > 6:
        return False
    if len(s) < 5:
        return True
    if s.endswith(("WS", "WT", "RT", "UN")):
        return False
    if s.endswith(("W", "R", "U")):
        return False
    return True

stock_scanner.py._merge_candidate_rows:
def _merge_candidate_rows(*sources, limit=180):
    """Union discovery sources by symbol without hiding a live rescue mover."""
    merged = {}
    order = []
    for source in sources:
        for row in source or []:
            if not isinstance(row, dict):
                continue
            symbol = str(row.get("symbol") or "").upper().strip()
            if not symbol:
                continue
            if symbol not in merged:
                merged[symbol] = {"symbol": symbol}
                order.append(symbol)
            for key, value in row.items():
                if value is not None:
                    merged[symbol][key] = value
    return [merged[symbol] for symbol in order[: max(1, int(limit))]]

stock_scanner.py._alpaca_rescue_candidates:
def _alpaca_rescue_candidates(phase):
    """Small live-discovery rescue set layered on top of Tradier's broad cache."""
    if not ALPACA_CONFIGURED:
        return []
    if phase == "regular":
        return get_movers()

    merged = {}
    errors = []
    if phase in {"premarket", "afterhours"}:
        for by in ("volume", "trades"):
            try:
                for row in get_most_actives(by=by, top=100):
                    symbol = str(row.get("symbol") or "").upper().strip()
                    if symbol:
                        merged[symbol] = {"symbol": symbol}
            except Exception as exc:
                errors.append(str(exc))
        if phase == "afterhours":
            try:
                for row in get_movers():
                    symbol = str(row.get("symbol") or "").upper().strip()
                    if symbol:
                        merged[symbol] = {"symbol": symbol}
            except Exception as exc:
                errors.append(str(exc))
    if errors and not merged:
        raise RuntimeError(" | ".join(errors[:2]))
    return list(merged.values())

stock_scanner.py.get_candidate_universe:
def get_candidate_universe(now_et):
    """Discover momentum candidates, preferring the full-market Tradier radar."""
    phase = market_session_mode(now_et)

    if USE_TRADIER and discover_tradier_candidates is not None:
        try:
            rows, meta = discover_tradier_candidates(
                TRADIER_TOKEN,
                likely_common_stock,
                top=FULL_MARKET_CANDIDATE_TOP,
            )
            print(
                "Full-market radar: "
                f"checked {meta.get('quotes_received', 0)}/"
                f"{meta.get('requested_symbols', meta.get('symbols', '?'))} symbols "
                f"({meta.get('coverage_pct', 0):.1f}% coverage); "
                f"returned {meta.get('candidates_returned', len(rows))} ignition candidates; "
                f"sub-$1 eligible={meta.get('sub_dollar_eligible', 0)}."
            )
            for warning in meta.get("warnings") or []:
                print("WARN full-market radar: " + str(warning))
            if rows:
                return rows
            raise RuntimeError("full-market radar returned no candidates")
        except Exception as exc:
            print(f"WARN full-market Tradier radar failed: {exc}")
            if not ALPACA_CONFIGURED:
                raise

    # Provider-degraded fallback. This preserves the older Alpaca discovery
    # path but it is explicitly not equivalent to full-market coverage.
    if phase == "regular":
        return get_movers()

    if phase in {"premarket", "afterhours"}:
        merged = {}
        errors = []
        for by in ("volume", "trades"):
            try:
                for row in get_most_actives(by=by, top=100):
                    symbol = str(row.get("symbol") or "").upper().strip()
                    if symbol:
                        merged[symbol] = {"symbol": symbol}
            except Exception as exc:
                errors.append(str(exc))
        if phase == "afterhours":
            try:
                for row in get_movers():
                    symbol = str(row.get("symbol") or "").upper().strip()
                    if symbol:
                        merged[symbol] = {"symbol": symbol}
            except Exception as exc:
                errors.append(str(exc))
        if merged:
            return list(merged.values())[:100]
        if errors:
            print("WARN extended-hours discovery: " + " | ".join(errors[:2]))
        return get_movers()

    return get_movers()

stock_scanner.py.get_snapshot:
def get_snapshot(symbol):
    q = urllib.parse.urlencode({"feed": LIVE_FEED})
    url = f"{DATA_BASE}/v2/stocks/{urllib.parse.quote(symbol)}/snapshot?{q}"
    return get_json(url)

stock_scanner.py.get_multi_snapshots:
def get_multi_snapshots(symbols, feed=None):
    """Fetch Alpaca snapshots in batches instead of one HTTP request per ticker."""
    symbols = [
        str(symbol).upper().strip()
        for symbol in symbols
        if str(symbol).strip()
    ]
    merged = {}
    for start in range(0, len(symbols), 100):
        chunk = symbols[start : start + 100]
        params = urllib.parse.urlencode(
            {
                "symbols": ",".join(chunk),
                "feed": feed or LIVE_FEED,
            }
        )
        payload = get_json(f"{DATA_BASE}/v2/stocks/snapshots?{params}")
        data = payload.get("snapshots") if isinstance(payload, dict) else None
        if not isinstance(data, dict):
            data = payload if isinstance(payload, dict) else {}
        for symbol, snapshot in data.items():
            if isinstance(snapshot, dict):
                merged[str(symbol).upper()] = snapshot
    return merged

stock_scanner.py.get_multi_bars:
def get_multi_bars(symbols, timeframe, start, end, limit=10000, feed=None):
    """Fetch bars for many symbols, following Alpaca pagination."""
    if not symbols:
        return {}

    merged = defaultdict(list)
    page_token = None
    pages = 0

    while True:
        query = {
            "symbols": ",".join(symbols),
            "timeframe": timeframe,
            "start": start.isoformat().replace("+00:00", "Z"),
            "end": end.isoformat().replace("+00:00", "Z"),
            "limit": limit,
            "adjustment": "raw",
            "feed": feed or LIVE_FEED,
            "sort": "asc",
        }
        if page_token:
            query["page_token"] = page_token

        params = urllib.parse.urlencode(query)
        data = get_json(f"{DATA_BASE}/v2/stocks/bars?{params}")
        for symbol, bars in (data.get("bars") or {}).items():
            merged[str(symbol).upper()].extend(bars or [])

        page_token = data.get("next_page_token")
        pages += 1
        if not page_token or pages >= 10:
            break

    return dict(merged)

stock_scanner.py.market_session_mode:
def market_session_mode(now_et):
    """Return premarket, regular, afterhours, or closed in New York time."""
    if now_et.weekday() >= 5:
        return "closed"
    minutes = now_et.hour * 60 + now_et.minute
    if (4 * 60) <= minutes < (9 * 60 + 30):
        return "premarket"
    if (9 * 60 + 30) <= minutes < (16 * 60):
        return "regular"
    if (16 * 60) <= minutes < (20 * 60):
        return "afterhours"
    return "closed"

stock_scanner.py.live_feed_available:
def live_feed_available(now_et):
    """Whether the configured live provider covers the current stock session."""
    phase = market_session_mode(now_et)
    if phase not in {"premarket", "regular", "afterhours"}:
        return False

    # Tradier production market data is consolidated and is used for the
    # scanner's live quote/volume/spread/intraday metrics when configured.
    if USE_TRADIER:
        return True

    if LIVE_FEED == "sip":
        return True

    # Alpaca Basic/IEX is the fallback and has a narrower useful window.
    minutes = now_et.hour * 60 + now_et.minute
    return (8 * 60) <= minutes < (17 * 60)

stock_scanner.py.session_window_minutes:
def session_window_minutes(now_et):
    phase = market_session_mode(now_et)
    if phase == "premarket":
        return 4 * 60, 9 * 60 + 30
    if phase == "afterhours":
        return 16 * 60, 20 * 60
    return 9 * 60 + 30, 16 * 60

stock_scanner.py.session_fraction:
def session_fraction(now_et):
    open_minutes, close_minutes = session_window_minutes(now_et)
    current_minutes = now_et.hour * 60 + now_et.minute
    total = max(1, close_minutes - open_minutes)
    if current_minutes <= open_minutes:
        return 1.0 / total
    if current_minutes >= close_minutes:
        return 1.0
    return max(1.0 / total, (current_minutes - open_minutes) / total)

stock_scanner.py.analyzer_aligned_volume_pace:
def analyzer_aligned_volume_pace(session_volume, avg_daily_volume_value, now_et):
    """Regular-hours relative volume using the same baseline as the Analyzer.

    The scanner keeps its historical time-of-day pace for ML continuity, while
    this aligned value is used for the compact UI/action signal so the two apps
    speak the same language.
    """
    if market_session_mode(now_et) != "regular":
        return None
    try:
        session_volume = float(session_volume)
        avg_daily_volume_value = float(avg_daily_volume_value)
    except (TypeError, ValueError):
        return None
    if session_volume < 0 or avg_daily_volume_value <= 0:
        return None
    expected = avg_daily_volume_value * session_fraction(now_et)
    if expected <= 0:
        return None
    return session_volume / expected

stock_scanner.py.risk_lane_for_price:
def risk_lane_for_price(price):
    try:
        value = float(price)
    except (TypeError, ValueError):
        return "UNKNOWN"
    if value < SUB_DOLLAR_CUTOFF:
        return "SUB-$1"
    if value <= SMALL_ACCOUNT_MAX_PRICE:
        return "$1-$50"
    return "ABOVE-$50"

stock_scanner.py.liquidity_floor_for:
def liquidity_floor_for(c):
    """Execution-quality floor; it never controls radar visibility."""
    phase = c.get("market_session") or "regular"
    sub_dollar = risk_lane_for_price(c.get("price")) == "SUB-$1"
    if sub_dollar:
        return (
            MIN_SUB_DOLLAR_EXTENDED_DOLLAR_VOLUME
            if phase in {"premarket", "afterhours"}
            else MIN_SUB_DOLLAR_DOLLAR_VOLUME
        )
    return (
        MIN_EXTENDED_DOLLAR_VOLUME
        if phase in {"premarket", "afterhours"}
        else MIN_TOTAL_DOLLAR_VOLUME
    )

stock_scanner.py.refresh_tradeability_score:
def refresh_tradeability_score(c):
    """Refresh the separate execution score after deeper live enrichment."""
    score = 0.0
    price = c.get("price")
    lane = c.get("risk_lane") or risk_lane_for_price(price)
    c["risk_lane"] = lane
    c["sub_dollar"] = lane == "SUB-$1"

    if c.get("live_price_available") is True:
        score += 25.0
    try:
        age = float(c.get("live_price_age_seconds"))
    except (TypeError, ValueError):
        age = None
    if age is not None and age <= MAX_ACTIONABLE_MARKET_DATA_AGE_SECONDS:
        score += 5.0

    try:
        spread = float(c.get("spread_pct"))
    except (TypeError, ValueError):
        spread = None
    if spread is not None:
        if spread <= 0.5:
            score += 25.0
        elif spread <= 1.0:
            score += 22.0
        elif spread <= 2.0:
            score += 17.0
        elif spread <= 4.0:
            score += 10.0
        elif spread <= 8.0:
            score += 4.0

    liquidity = max(0.0, float(c.get("liquidity_dollar_volume") or 0.0))
    if liquidity > 0:
        import math
        score += scale(math.log10(max(1.0, liquidity)), 4.5, 7.3, 25.0)

    try:
        pace = float(
            c.get("volume_pace_display")
            if c.get("volume_pace_display") is not None
            else c.get("volume_pace")
        )
    except (TypeError, ValueError):
        pace = None
    score += scale(pace, 0.2, 4.0, 12.0)
    score += 8.0 if lane == "$1-$50" else 6.0 if lane == "ABOVE-$50" else 2.0
    c["tradeability_score"] = round(max(0.0, min(100.0, score)), 1)
    return c["tradeability_score"]

stock_scanner.py.live_bonus_score:
def live_bonus_score(c):
    score = 0.0
    score += scale(c.get("volume_pace"), 1.0, 5.0, 12.0)
    score += scale(c.get("momentum_5m"), 0.0, 3.0, 10.0)
    score += scale(c.get("momentum_15m"), 0.0, 6.0, 8.0)
    return round(score, 1)

stock_scanner.py.critical_fail_count:
def critical_fail_count(c):
    """Count execution failures without making risky names invisible."""
    count = 0
    price = float(c.get("price") or 0.0)
    if price < MIN_DETECTION_PRICE:
        count += 1

    liquidity_floor = liquidity_floor_for(c)
    if c.get("liquidity_source") in {
        "delayed_sip",
        "tradier_consolidated",
        "tradier_extended",
        "historical_tradier_replay",
        "live_sip_extended",
    }:
        if c.get("liquidity_dollar_volume", 0) < liquidity_floor:
            count += 1
    else:
        if c.get("dollar_volume", 0) < MIN_RAW_IEX_DOLLAR_VOLUME_FALLBACK:
            count += 1
        if c.get("liquidity_dollar_volume", 0) < liquidity_floor:
            count += 1
    return count

stock_scanner.py.ranking_key:
def ranking_key(c):
    """Rank analyzed candidates by Tradeability; eligibility gates stay separate."""
    return tradeability_rank_key(c)

stock_scanner.py.assign_setup_grades:
def assign_setup_grades(rows, now_et):
    for c in rows:
        assign_setup_grade(c, now_et)

stock_scanner.py.scanner_action_signal:
def scanner_action_signal(c, now_et=None, *, use_behavior=False):
    """Compact scanner-level review cue; Analyzer remains final confirmation.

    Behavior-aware overrides remain available for paired research, but are
    disabled by default because the first causal replay did not improve ACTION
    quality. Production stays on the simpler validated rule path.
    """
    grade = str(c.get("setup_grade") or "REJECT").upper()
    phase = str(c.get("market_session") or "")
    if now_et is not None:
        phase = market_session_mode(now_et)

    failed = int(c.get("failed_count") or 0)
    critical = int(c.get("critical_fail_count") or 0)
    warnings = c.get("tradability_warnings") or []
    spread = c.get("spread_pct")
    day_pct = c.get("day_pct")
    from_high = c.get("distance_from_high_pct")
    dist_vwap = c.get("distance_from_vwap_pct")
    m5 = c.get("momentum_5m")
    m15 = c.get("momentum_15m")
    pace = (
        c.get("volume_pace_display")
        if c.get("volume_pace_display") is not None
        else c.get("volume_pace")
    )

    def num(value):
        try:
            return float(value)
        except (TypeError, ValueError):
            return None

    spread = num(spread)
    day_pct = num(day_pct)
    from_high = num(from_high)
    dist_vwap = num(dist_vwap)
    m5 = num(m5)
    m15 = num(m15)
    pace = num(pace)
    explosion = num(c.get("explosion_score")) or 0.0
    tradeability = num(c.get("tradeability_score")) or 0.0
    lane = c.get("risk_lane") or risk_lane_for_price(c.get("price"))

    if c.get("radar_only"):
        return {
            "label": "DATA CHECK",
            "tier": "blocked",
            "reason": "Full-market radar detected the move, but deeper live bars have not yet confirmed an actionable price, VWAP and spread.",
        }

    failed_breakout = bool(num(c.get("failed_breakout")) or 0) if use_behavior else False
    vwap_rejection = bool(num(c.get("vwap_rejection")) or 0) if use_behavior else False
    vwap_reclaim = bool(num(c.get("vwap_reclaim")) or 0) if use_behavior else False
    volume_accelerating = bool(num(c.get("volume_accelerating")) or 0) if use_behavior else False
    breakout_holding = bool(num(c.get("breakout_holding")) or 0) if use_behavior else False
    stair_breakdown = bool(num(c.get("stair_breakdown")) or 0) if use_behavior else False
    bounce_leg_code = num(c.get("bounce_leg_code")) if use_behavior else None
    pullback_quality = num(c.get("pullback_quality_score")) if use_behavior else None

    if phase != "regular":
        if explosion >= 65.0:
            label = "SUB-$1 EXPLOSIVE WATCH" if lane == "SUB-$1" else "EXPLOSIVE WATCH"
            return {
                "label": label,
                "tier": "caution" if lane == "SUB-$1" else "watch",
                "reason": "The full-market radar detected strong extended-hours ignition. Confirm consolidated spread, live bars and a non-chasing entry in Analyzer.",
            }
        return {
            "label": "EXTENDED WATCH",
            "tier": "watch",
            "reason": "Extended-hours conditions require extra confirmation.",
        }

    if lane == "SUB-$1" and explosion >= 55.0:
        if critical == 0 and failed <= 1 and tradeability >= 65.0 and (spread is None or spread <= 3.0):
            return {
                "label": "HIGH-RISK REVIEW",
                "tier": "caution",
                "reason": "Sub-$1 ignition is strong and execution metrics are comparatively favorable, but this remains an extreme-risk setup; use Analyzer before any decision.",
            }
        return {
            "label": "SUB-$1 EXPLOSIVE WATCH",
            "tier": "caution",
            "reason": "A sub-$1 explosion was detected, but liquidity, spread or confirmation is not strong enough for a normal actionable signal.",
        }

    if grade == "REJECT" or critical > 0 or failed >= 2:
        reason = (
            (c.get("failed_filters") or [None])[0]
            or "Scanner safety filters reject the setup."
        )
        if explosion >= 65.0:
            return {
                "label": "EXPLOSIVE / NO TRADE",
                "tier": "avoid",
                "reason": "The move is real enough to display, but execution-quality filters reject an entry: " + reason,
            }
        return {"label": "NO TRADE", "tier": "avoid", "reason": reason}

    if spread is not None and spread > 4.5:
        return {
            "label": "NO TRADE",
            "tier": "avoid",
            "reason": "Live spread is too wide for a clean momentum entry.",
        }

    if grade == "C" or warnings or (spread is not None and spread > 2.5):
        return {
            "label": "CAUTION",
            "tier": "caution",
            "reason": "Setup or execution quality still has a material warning.",
        }

    # Behavior-state checks refine *timing* only. They never override hard
    # filters, spread/liquidity warnings, or the Analyzer's final trade plan.
    if failed_breakout:
        return {
            "label": "WAIT",
            "tier": "caution",
            "reason": "A recent breakout failed back below its trigger; wait for a reclaim or a fresh base before entering.",
        }

    if vwap_rejection:
        return {
            "label": "WAIT",
            "tier": "caution",
            "reason": "Price recently rejected at VWAP; wait for a clean reclaim and hold before entering.",
        }

    if stair_breakdown:
        return {
            "label": "CAUTION",
            "tier": "caution",
            "reason": "The higher multi-session plateau has broken down; continuation risk is elevated.",
        }

    if not bool(c.get("above_vwap")):
        return {
            "label": "WAIT",
            "tier": "watch",
            "reason": "Price is not holding above VWAP.",
        }

    # Strong movers can still be poor chase points. This deliberately catches
    # cases such as a +50% mover that the full Analyzer may prefer on pullback.
    if (
        (day_pct is not None and day_pct >= 50.0)
        or (dist_vwap is not None and dist_vwap >= 8.0)
    ):
        return {
            "label": "WAIT PULLBACK",
            "tier": "pullback",
            "reason": "Momentum is strong, but the current price is extended enough to avoid chasing.",
        }

    strong_momentum = (
        m5 is not None and m5 >= 0.5
        and m15 is not None and m15 >= 1.0
    )
    strong_participation = pace is not None and pace >= 1.5
    near_high = from_high is not None and from_high <= 3.0
    very_near_high = from_high is not None and from_high <= 1.25
    execution_ok = spread is None or spread <= 2.0

    # Behavior-aware promotions remain research-only. Replay showed these
    # structures can be explosive without reliably improving trade quality.
    if (
        grade in {"A", "B"}
        and breakout_holding
        and volume_accelerating
        and execution_ok
        and m5 is not None and m5 >= 0
    ):
        if grade == "A":
            return {
                "label": "ANALYZE NOW",
                "tier": "watch",
                "reason": "The A-grade breakout deserves immediate review, but replay does not support an automatic entry call; confirm the exact entry and stop in Analyzer.",
            }
        return {
            "label": "BREAKOUT WATCH",
            "tier": "breakout",
            "reason": "The breakout is holding with accelerating volume, but the overall setup is still B-grade; wait for Analyzer confirmation before entering.",
        }

    if (
        grade in {"A", "B"}
        and vwap_reclaim
        and bounce_leg_code is not None and bounce_leg_code > 0
        and pullback_quality is not None and pullback_quality >= 65
        and execution_ok
        and m5 is not None and m5 > 0
    ):
        if grade == "A":
            return {
                "label": "ANALYZE NOW",
                "tier": "watch",
                "reason": "The A-grade pullback/bounce deserves immediate review, but replay does not support an automatic entry call; confirm the entry zone in Analyzer.",
            }
        return {
            "label": "BOUNCE WATCH",
            "tier": "breakout",
            "reason": "A constructive bounce has reclaimed VWAP, but the overall setup is still B-grade; wait for Analyzer confirmation before entering.",
        }

    if (
        grade in {"A", "B"}
        and bounce_leg_code is not None and bounce_leg_code < 0
        and (pullback_quality is None or pullback_quality < 75)
    ):
        return {
            "label": "WAIT PULLBACK",
            "tier": "pullback",
            "reason": "The stock is still in a pullback leg; wait for the dip to hold and a bounce/reclaim to confirm.",
        }

    if grade == "A" and strong_momentum and strong_participation and near_high and execution_ok:
        if very_near_high:
            return {
                "label": "BREAKOUT WATCH",
                "tier": "breakout",
                "reason": "High-quality momentum is pressing the session high; confirm the breakout in Analyzer.",
            }
        return {
            "label": "ANALYZE NOW",
            "tier": "watch",
            "reason": "Scanner-level momentum, participation, VWAP and execution checks are aligned; open Analyzer now for the actual entry, stop and targets.",
        }

    if (
        grade in {"A", "B"}
        and m5 is not None and m5 > 0
        and (m15 is None or m15 >= 0)
        and pace is not None and pace >= 1.2
        and very_near_high
    ):
        return {
            "label": "BREAKOUT WATCH",
            "tier": "breakout",
            "reason": "Price is pressing the high with positive momentum; wait for confirmation.",
        }

    if (
        grade in {"A", "B"}
        and dist_vwap is not None and dist_vwap >= 5.5
    ):
        return {
            "label": "WAIT PULLBACK",
            "tier": "pullback",
            "reason": "Setup is attractive, but price is stretched above VWAP.",
        }

    return {
        "label": "WATCH",
        "tier": "watch",
        "reason": "Interesting setup, but scanner-level entry conditions are not fully aligned yet.",
    }

stock_scanner.py._scanner_data_integrity:
def _scanner_data_integrity(c, now_et):
    reasons = []

    def source_family(value):
        text = str(value or "").lower().strip()
        if "tradier" in text:
            return "tradier"
        if "sip" in text or "consolidated" in text:
            return "sip"
        if "iex" in text:
            return "iex"
        return "unknown"

    quote_source = str(c.get("live_quote_source") or "").lower()
    intraday_source = str(c.get("live_intraday_source") or "").lower()
    quote_family = source_family(quote_source)
    intraday_family = source_family(intraday_source)

    quote_consolidated = quote_family in {"tradier", "sip"}
    intraday_consolidated = intraday_family in {"tradier", "sip"}
    if not quote_consolidated:
        reasons.append("live quote source is not consolidated")
    if not intraday_source:
        reasons.append("live intraday source is missing")
    elif not intraday_consolidated:
        reasons.append("live intraday source is not consolidated")
    if (
        quote_consolidated
        and intraday_consolidated
        and quote_family != intraday_family
    ):
        reasons.append(
            "live quote and intraday technicals come from different consolidated providers"
        )

    now_utc = now_et.astimezone(timezone.utc)
    if c.get("live_price_available") is False:
        reasons.append("live price is unavailable")
    price_dt=parse_timestamp(
        c.get("live_price_timestamp") or c.get("latest_trade_time")
    )
    if price_dt is None:
        reasons.append("live price timestamp is missing")
    else:
        price_future=(price_dt.astimezone(timezone.utc)-now_utc).total_seconds()
        if price_future > MAX_FUTURE_CLOCK_SKEW_SECONDS:
            c["live_price_age_seconds"]=None
            reasons.append(f"live price timestamp is {price_future:.0f}s in the future")
            price_dt=None
    if price_dt is not None:
        price_age=max(
            0.0,(now_utc-price_dt.astimezone(timezone.utc)).total_seconds()
        )
        c["live_price_age_seconds"]=round(price_age,2)
        if price_age > MAX_ACTIONABLE_MARKET_DATA_AGE_SECONDS:
            reasons.append(f"live price is stale ({price_age:.0f}s old)")

    for label, key in (
        ("trade", "latest_trade_time"),
        ("quote", "latest_quote_time"),
    ):
        dt = parse_timestamp(c.get(key))
        if dt is None:
            reasons.append(f"latest {label} timestamp is missing")
            continue
        age = max(
            0.0,(now_utc-dt.astimezone(timezone.utc)).total_seconds()
        )
        future_seconds=(dt.astimezone(timezone.utc)-now_utc).total_seconds()
        if future_seconds > MAX_FUTURE_CLOCK_SKEW_SECONDS:
            c[f"{label}_age_seconds"] = None
            reasons.append(f"latest {label} timestamp is {future_seconds:.0f}s in the future")
            continue
        c[f"{label}_age_seconds"] = round(age, 2)
        if age > MAX_ACTIONABLE_MARKET_DATA_AGE_SECONDS:
            reasons.append(f"latest {label} is stale ({age:.0f}s old)")

    for key, label in (
        ("price", "price"),
        ("vwap", "VWAP"),
        ("momentum_5m", "5-minute momentum"),
        ("momentum_15m", "15-minute momentum"),
        ("spread_pct", "live spread"),
    ):
        if c.get(key) is None:
            reasons.append(f"{label} is missing")

    return not reasons, reasons

stock_scanner.py.evaluate_base_filters:
def evaluate_base_filters(c):
    reasons = []
    price = float(c.get("price") or 0.0)
    lane = c.get("risk_lane") or risk_lane_for_price(price)
    c["risk_lane"] = lane
    c["sub_dollar"] = lane == "SUB-$1"

    if price < MIN_DETECTION_PRICE:
        reasons.append(f"price < ${MIN_DETECTION_PRICE:.2f} detection floor")
    if c.get("day_pct") is None or c["day_pct"] < MIN_DAY_PCT:
        reasons.append("day gain < 3%")

    phase = c.get("market_session") or "regular"
    liquidity_floor = liquidity_floor_for(c)
    liquidity_label = (
        f"${liquidity_floor / 1_000_000:.2f}M"
        if liquidity_floor < 1_000_000
        else f"${liquidity_floor / 1_000_000:.0f}M"
    )

    if c.get("liquidity_source") in {
        "delayed_sip",
        "tradier_consolidated",
        "tradier_extended",
        "historical_tradier_replay",
        "live_sip_extended",
    }:
        if c.get("liquidity_dollar_volume", 0) < liquidity_floor:
            source_label = (
                "Tradier consolidated dollar volume"
                if str(c.get("liquidity_source") or "").startswith("tradier")
                else "consolidated dollar volume"
            )
            reasons.append(f"{source_label} < {liquidity_label}")
    else:
        if c.get("dollar_volume", 0) < MIN_RAW_IEX_DOLLAR_VOLUME_FALLBACK:
            reasons.append("IEX dollar volume < $25k (fallback)")
        if c.get("liquidity_dollar_volume", 0) < liquidity_floor:
            reasons.append(f"est. total dollar volume < {liquidity_label} (fallback)")

    if c.get("intraday_range_pct") is None or c["intraday_range_pct"] < MIN_INTRADAY_RANGE_PCT:
        reasons.append("range < 3%")
    if c.get("distance_from_high_pct") is None or c["distance_from_high_pct"] > MAX_DISTANCE_FROM_HIGH_PCT:
        reasons.append("> 8% below high")
    if phase == "regular" and not c.get("above_vwap"):
        reasons.append("below VWAP")
    return reasons

stock_scanner.py.evaluate_tradability_warnings:
def evaluate_tradability_warnings(c):
    warnings = []
    lane = c.get("risk_lane") or risk_lane_for_price(c.get("price"))
    if lane == "SUB-$1":
        warnings.append("SUB-$1 EXTREME RISK: elevated volatility, slippage, dilution and manipulation risk")
    elif lane == "ABOVE-$50":
        warnings.append("above the small-account $1-$50 focus lane")

    spread = c.get("spread_pct")
    source = str(c.get("live_quote_source") or "")
    spread_label = "consolidated spread" if source.startswith("tradier") else "IEX spread"
    if spread is None:
        warnings.append(f"{spread_label} unavailable")
    elif spread > MAX_IEX_SPREAD_WARNING_PCT:
        warnings.append(f"{spread_label} > {MAX_IEX_SPREAD_WARNING_PCT:.0f}%")
    elif lane == "SUB-$1" and spread > 3.0:
        warnings.append("sub-$1 spread > 3%")
    return warnings

stock_scanner.py.enrich_delayed_sip_liquidity:
def enrich_delayed_sip_liquidity(rows, now_utc, now_et):
    """Use delayed SIP only when consolidated Tradier liquidity is not active."""
    if not rows:
        return

    if USE_TRADIER:
        for row in rows:
            row["sip_liquidity_status"] = "not_needed_tradier_consolidated"
        return

    if market_session_mode(now_et) in {"premarket", "afterhours"}:
        for row in rows:
            row["sip_liquidity_status"] = "extended_session_uses_live_iex"
        return

    et = ZoneInfo("America/New_York")
    session_dates = [c.get("session_date") for c in rows if c.get("session_date")]
    if not session_dates:
        return

    session_date = Counter(session_dates).most_common(1)[0][0]
    try:
        session_day = datetime.strptime(session_date, "%Y-%m-%d").date()
    except ValueError:
        return

    start_et = datetime(
        session_day.year, session_day.month, session_day.day, 9, 30, tzinfo=et
    )
    close_et = datetime(
        session_day.year, session_day.month, session_day.day, 16, 0, tzinfo=et
    )

    if session_day == now_et.date() and is_regular_session(now_et):
        end_et = min(close_et, now_et - timedelta(minutes=SIP_LIQUIDITY_DELAY_MINUTES))
    else:
        end_et = close_et

    if end_et <= start_et:
        for c in rows:
            c["sip_liquidity_status"] = "not_available_yet"
        return

    symbols = [c["symbol"] for c in rows]
    try:
        bars_by_symbol = get_multi_bars(
            symbols,
            SIP_LIQUIDITY_TIMEFRAME,
            start_et.astimezone(timezone.utc),
            end_et.astimezone(timezone.utc),
            limit=10000,
            feed=HISTORICAL_FEED,
        )
    except Exception as exc:
        for c in rows:
            c["sip_liquidity_status"] = "fallback_iex_estimate"
            c["sip_liquidity_error"] = str(exc)
        print(f"WARN delayed SIP liquidity enrichment: {exc}")
        return

    for c in rows:
        bars = bars_by_symbol.get(c["symbol"], [])
        sip_volume = 0.0
        sip_dollar = 0.0
        for b in bars:
            vol = float(b.get("v") or 0)
            px = float(b.get("vw") or b.get("c") or 0)
            if vol > 0 and px > 0:
                sip_volume += vol
                sip_dollar += vol * px

        if sip_volume > 0 and sip_dollar > 0:
            c["sip_delayed_volume"] = int(sip_volume)
            c["sip_delayed_dollar_volume"] = round(sip_dollar, 2)
            c["sip_liquidity_asof"] = end_et.isoformat()
            c["sip_liquidity_status"] = "available"
            c["liquidity_source"] = "delayed_sip"
            c["liquidity_dollar_volume"] = round(sip_dollar, 2)
        else:
            c["sip_liquidity_status"] = "no_bars_fallback_iex_estimate"

        refresh_quality(c)

stock_scanner.py.merge_radar_fields:
def merge_radar_fields(candidate, radar_row):
    """Attach full-market detection evidence without copying raw provider data."""
    if not candidate or not radar_row:
        return candidate
    if radar_row.get("tradeability_score") is not None:
        candidate["radar_tradeability_score"] = radar_row.get("tradeability_score")
    for key, value in radar_row.items():
        if key in {"symbol", "_tradier_quote", "tradeability_score"}:
            continue
        candidate[key] = value
    candidate["risk_lane"] = radar_row.get("risk_lane") or risk_lane_for_price(
        candidate.get("price")
    )
    candidate["sub_dollar"] = candidate["risk_lane"] == "SUB-$1"
    return candidate

stock_scanner.py.daily_history_context:
def daily_history_context(symbol, now_utc, current_day=None):
    """Return average volume, daily trend, and causal multi-session structure."""
    bars = []
    source = None

    # Timeframe Fit depends on multi-week history. Prefer Tradier consolidated
    # daily candles when Tradier is the configured live provider so the
    # classification does not create an unnecessary Alpaca dependency.
    if USE_TRADIER and get_tradier_history_bars is not None:
        try:
            bars = get_tradier_history_bars(
                symbol,
                TRADIER_TOKEN,
                now_utc - timedelta(days=100),
                now_utc,
                interval="daily",
            )
            if bars:
                source = "tradier_consolidated_daily"
        except Exception:
            bars = []

    if not bars:
        try:
            bars = get_bars(
                symbol,
                "1Day",
                now_utc - timedelta(days=100),
                now_utc,
                80,
                feed=HISTORICAL_FEED,
            )
            if bars:
                source = f"alpaca_{HISTORICAL_FEED}_daily"
        except Exception:
            bars = get_bars(
                symbol,
                "1Day",
                now_utc - timedelta(days=100),
                now_utc,
                80,
                feed=LIVE_FEED,
            )
            if bars:
                source = f"alpaca_{LIVE_FEED}_daily"

    if not bars:
        return {}

    today_et = now_utc.astimezone(ZoneInfo("America/New_York")).date().isoformat()
    completed_all = [
        b for b in bars
        if str(b.get("t", ""))[:10] != today_et
    ][-60:]
    completed = completed_all[-20:]

    volume_rows = [
        float(b["v"])
        for b in completed
        if b.get("v") is not None and float(b.get("v") or 0) > 0
    ]

    current_price = None
    if current_day:
        try:
            current_price = float(current_day.get("c") or 0) or None
        except Exception:
            current_price = None
    if current_price is None and completed_all:
        try:
            current_price = float(completed_all[-1].get("c") or 0) or None
        except Exception:
            current_price = None

    def close_n_back(sessions):
        if len(completed_all) < sessions:
            return None
        try:
            return float(completed_all[-sessions].get("c") or 0) or None
        except Exception:
            return None

    def trailing_return(sessions):
        old = close_n_back(sessions)
        if current_price is None or old in (None, 0):
            return None
        return round(pct_change(current_price, old), 2)

    def moving_average(sessions):
        rows = completed_all[-sessions:]
        vals = []
        for row in rows:
            try:
                value = float(row.get("c") or 0)
            except Exception:
                value = 0
            if value > 0:
                vals.append(value)
        if len(vals) < min(sessions, max(5, sessions - 2)):
            return None
        return round(sum(vals) / len(vals), 4)

    ma10 = moving_average(10)
    ma20 = moving_average(20)
    ma40 = moving_average(40)

    recent_highs = []
    for row in completed_all[-45:]:
        try:
            value = float(row.get("h") or 0)
        except Exception:
            value = 0
        if value > 0:
            recent_highs.append(value)
    if current_day:
        try:
            today_high = float(current_day.get("h") or 0)
        except Exception:
            today_high = 0
        if today_high > 0:
            recent_highs.append(today_high)
    recent_high = max(recent_highs) if recent_highs else None

    alignment = None
    if ma10 is not None and ma20 is not None and ma40 is not None:
        if ma10 > ma20 > ma40:
            alignment = "BULLISH"
        elif ma10 < ma20 < ma40:
            alignment = "BEARISH"
        else:
            alignment = "MIXED"

    context = {
        "avg_daily_volume": (
            sum(volume_rows) / len(volume_rows)
            if volume_rows
            else None
        ),
        "daily_context_source": source,
        "daily_history_sessions": len(completed_all),
        "daily_return_5d_pct": trailing_return(5),
        "daily_return_20d_pct": trailing_return(20),
        "daily_return_40d_pct": trailing_return(40),
        "daily_ma_10": ma10,
        "daily_ma_20": ma20,
        "daily_ma_40": ma40,
        "daily_above_ma20": (
            bool(current_price >= ma20)
            if current_price is not None and ma20 is not None
            else None
        ),
        "daily_above_ma40": (
            bool(current_price >= ma40)
            if current_price is not None and ma40 is not None
            else None
        ),
        "daily_ma_alignment": alignment,
        "daily_recent_high": round(recent_high, 4) if recent_high is not None else None,
        "daily_from_recent_high_pct": (
            round((current_price / recent_high - 1.0) * 100.0, 2)
            if current_price is not None and recent_high
            else None
        ),
    }

    if multi_session_behavior_features is not None and current_day:
        try:
            context.update(
                multi_session_behavior_features(
                    completed,
                    current_day,
                    atr_pct=None,
                )
            )
        except Exception:
            pass
    return context

stock_scanner.py.get_live_bars:
def get_live_bars(symbol, timeframe, start, end, limit=10000):
    """Use Tradier consolidated Time & Sales for live intraday bars when configured."""
    if USE_TRADIER:
