    return {
        "status": c.get("news_status"),
        "category": cat.get("category"),
        "score": cat.get("catalyst_score"),
        "published_at": cat.get("published_at") or cat.get("created_at"),
        "age_hours": cat.get("age_hours"),
        "headline": shorten(cat.get("headline"), 220),
        "matched_keywords": cat.get("matched_keywords") or [],
    }

stock_scanner.py.print_setup_grades:
def print_setup_grades(rows, now_et):
    phase = market_session_mode(now_et)
    mode = {
        "premarket": "PRE-MARKET LIVE" if live_feed_available(now_et) else "PRE-MARKET / LIVE DATA UNAVAILABLE",
        "regular": "REGULAR HOURS LIVE",
        "afterhours": "AFTER-HOURS LIVE" if live_feed_available(now_et) else "AFTER-HOURS / LIVE DATA UNAVAILABLE",
        "closed": "MARKET CLOSED / PREVIEW",
    }[phase]
    print(f"\nSETUP GRADES / ALERT READINESS - {mode}")
    print("-" * 110)
    for c in rows[:WATCHLIST_SIZE]:
        flags = ", ".join(c.get("setup_flags", [])) or "none"
        reasons = "; ".join(c.get("grade_reasons", [])) or "-"
        tier = c.get("alert_tier") or "NONE"
        print(
            f"{c['symbol']}: grade {c.get('setup_grade', '-')} {c.get('setup_label', '')} "
            f"| alert {tier} | flags: {flags}"
        )
        print(f"  {reasons}")

    if phase in {"premarket", "afterhours"}:
        print(
            "Extended-hours setups are capped at B/WATCH. A/HIGH is reserved for "
            "regular-hours confirmation because liquidity and spreads are less reliable."
        )
    elif phase == "closed":
        print("Market is closed; setup grades are preview-only.")

stock_scanner.py.main:
def main():
    scan_started = time.perf_counter()
    stage_started = scan_started
    performance = {}

    def mark_stage(name):
        nonlocal stage_started
        current = time.perf_counter()
        performance[name] = round(current - stage_started, 2)
        stage_started = current

    now_utc = datetime.now(timezone.utc)
    now_et = now_utc.astimezone(ZoneInfo("America/New_York"))

    print(f"Momentum scan v{SCANNER_VERSION} started: {now_et:%Y-%m-%d %H:%M:%S %Z}")
    phase = market_session_mode(now_et)
    phase_label = {
        "premarket": "PRE-MARKET",
        "regular": "REGULAR MARKET SESSION",
        "afterhours": "AFTER-HOURS",
        "closed": "MARKET CLOSED / TEST",
    }[phase]
    print("Mode: " + phase_label)
    if USE_TRADIER:
        print(
            "Data: Tradier consolidated live quotes/volume/spread/Time & Sales; "
            "Alpaca discovery/news/history retained."
        )
    else:
        print(
            f"Data: Alpaca live momentum = {LIVE_FEED.upper()}; liquidity prefers "
            "delayed consolidated SIP in regular hours; IEX scaling is fallback only."
        )
    if phase in {"premarket", "afterhours"} and not live_feed_available(now_et):
        print(
            "WARN configured live feed is not available at this extended-hours time. "
            "IEX live coverage is approximately 8:00 AM-5:00 PM ET; SIP is required "
            "for full 4:00 AM-8:00 PM ET live coverage."
        )

    candidates = get_candidate_universe(now_et)
    print(f"Combined discovery returned {len(candidates)} candidate symbols.")

    discovery_meta = (
        get_last_discovery_meta()
        if get_last_discovery_meta is not None
        else {}
    )

    quote_symbols = [
        str(row.get("symbol") or "").upper().strip()
        for row in candidates
        if row.get("symbol")
    ]
    tradier_quotes = {}
    price_provider_errors = [provider_problem(e.get("error"), "tradier") for e in discovery_meta.get("batch_errors", [])]
    if USE_TRADIER:
        # Full-market discovery already paid for these quotes. Reuse them so a
        # 6,000-symbol sweep is not followed by a redundant second request.
        tradier_quotes = {
            str(row.get("symbol") or "").upper().strip(): row.get("_tradier_quote")
            for row in candidates
            if row.get("symbol") and isinstance(row.get("_tradier_quote"), dict)
        }
        missing_quote_symbols = [
            symbol for symbol in quote_symbols if symbol not in tradier_quotes
        ]
        if missing_quote_symbols:
            try:
                tradier_quotes.update(
                    get_tradier_quotes(missing_quote_symbols, TRADIER_TOKEN)
                )
            except Exception as exc:
                price_provider_errors.append(provider_problem(exc, "tradier"))
                print("WARN Tradier candidate quote refill failed: " + price_provider_errors[-1]["state"])
        print(
            f"Tradier candidate quotes available for "
            f"{len(tradier_quotes)}/{len(quote_symbols)} candidates "
            f"({len(quote_symbols) - len(missing_quote_symbols)} reused from radar)."
        )

    alpaca_snapshots = {}
    # Tradier quote rows contain the live price, previous close, high/low,
    # volume and spread needed to begin enrichment. Do not let an unrelated
    # Alpaca credential problem disable a healthy consolidated radar.
    needs_alpaca_snapshots = bool(
        ALPACA_CONFIGURED
        and (
            not USE_TRADIER
            or any(symbol not in tradier_quotes for symbol in quote_symbols)
        )
    )
    if needs_alpaca_snapshots:
        try:
            alpaca_snapshots = get_multi_snapshots(
                quote_symbols,
                feed=LIVE_FEED,
            )
            print(
                f"Alpaca batched snapshots loaded for "
                f"{len(alpaca_snapshots)}/{len(quote_symbols)} candidates."
            )
        except Exception as exc:
            price_provider_errors.append(provider_problem(exc, "alpaca"))
            print("WARN Alpaca batch snapshots failed: " + price_provider_errors[-1]["state"])
            alpaca_snapshots = {}

    rows = []
    rejection_counts = Counter()
    excluded_symbols = []

    for mover in candidates:
        symbol = str(mover.get("symbol", "")).upper().strip()
        if not symbol:
            continue

        if not likely_common_stock(symbol):
            excluded_symbols.append(symbol)
            continue

        quote_row = tradier_quotes.get(symbol)
        try:
            c = analyze_snapshot(
                symbol,
                quote_row,
                alpaca_snapshots.get(symbol, {}),
                now_utc=now_utc,
            )
        except Exception as exc:
            print(f"WARN {symbol}: snapshot error: {exc}")
            rejection_counts["API/data error"] += 1
            c = None

        if c is None and mover.get("explosion_score") is not None:
            c = radar_only_candidate(mover, quote_row, now_utc)
            if c is not None:
                rejection_counts["radar-only pending deep confirmation"] += 1

        if c is None:
            rejection_counts["missing market data"] += 1
            continue

        c["live_price_provider_errors"] = list(price_provider_errors)
        merge_radar_fields(c, mover)
        c["market_session"] = phase
        c["session_date"] = now_et.date().isoformat()
        refresh_quality(c)
        rows.append(c)

    # A live scan that discovered symbols but could not build even one market
    # row is a provider/data-integrity failure, not a legitimate "zero ideas"
    # result. Fail before writing latest_scan.json so the UI keeps the prior
    # usable snapshot instead of replacing it with an empty dashboard.
    if is_active_market_session(now_et) and (candidates or price_provider_errors) and not rows:
        raise RuntimeError(
            "LIVE PRICE UNAVAILABLE — the scanner discovered symbols but could not "
            "validate any fresh, symbol-matched market prices. "
            "Preserving the previous scanner snapshot instead of publishing zero candidates. "
            + "; ".join(e["provider"] + ": " + e["state"] for e in price_provider_errors)
        )

    # Tradier rows already carry consolidated live liquidity. Alpaca fallback
    # rows still use the delayed-SIP enrichment path when it is available.
    enrich_delayed_sip_liquidity(rows, now_utc, now_et)
    mark_stage("discovery_and_base")

    rejection_counts = Counter(
        reason for c in rows for reason in c.get("failed_filters", [])
    )

    rows.sort(key=ranking_key, reverse=True)

    if is_active_market_session(now_et):
        enrich_targets = select_enrichment_targets(rows, phase)
        worker_count = max(
            1,
            min(MAX_ENRICH_WORKERS, len(enrich_targets)),
        )
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            futures = {
                executor.submit(
                    enrich_live,
                    c,
                    now_utc,
                    now_et,
                ): c
                for c in enrich_targets
            }
            for future in as_completed(futures):
                c = futures[future]
                try:
                    future.result()
                except Exception as exc:
                    c["enrichment_error"] = str(exc)
    else:
        for c in rows:
            c["live_data_status"] = "skipped_market_closed"

    rows.sort(key=ranking_key, reverse=True)
    mark_stage("live_enrichment")

    # One batched news call for the displayed watchlist.
    enrich_news(rows, now_utc)

    rows.sort(key=ranking_key, reverse=True)
    mark_stage("news")

    historical_targets = rows[:HISTORICAL_TOP]
    if FORCE_TRADIER_DISCOVERY:
        for c in historical_targets:
            c["historical"] = {
                "status": "not_requested_durable_tradier_scan",
                "message": (
                    "Same-ticker historical analog enrichment is skipped in the "
                    "durable learning scan so Alpaca cannot block scan logging."
                ),
            }
    elif is_regular_session(now_et) and historical_targets:
        worker_count = max(
            1,
            min(MAX_HISTORY_WORKERS, len(historical_targets)),
        )
        with ThreadPoolExecutor(max_workers=worker_count) as executor:
            futures = {
                executor.submit(
                    historical_continuation,
                    c["symbol"],
                    c.get("day_pct"),
                    now_utc,
                    now_et,
                ): c
                for c in historical_targets
            }
            for future in as_completed(futures):
                c = futures[future]
                try:
                    c["historical"] = future.result()
                except Exception as exc:
                    c["historical"] = {
                        "status": "error",
                        "message": str(exc),
                    }
    else:
        for c in historical_targets:
            c["historical"] = {
                "status": "skipped_off_hours",
                "message": (
                    "Historical intraday comparison activates during "
                    "regular market hours."
                ),
            }

    mark_stage("historical")

    # Rule-based setup grades remain the safety gate. ML is applied only after
    # those rules are complete and retains its validation requirements.
    # Tradeability remains the ranking criterion regardless of ML status.
    assign_setup_grades(rows, now_et)

    if phase == "regular" and apply_scanner_ml is not None:
        try:
            ml_summary = apply_scanner_ml(rows, now_et)
        except Exception as exc:
            ml_summary = {
                "status": "error",
                "validated": False,
                "version": "scanner-ml-v1",
                "error": str(exc)[:240],
            }
            for row in rows:
                row["ml_status"] = "error"
                row["ml_validated"] = False
                row["ml_continuation_prob_pct"] = None
                row["opportunity_score"] = row.get("score")
    else:
        ml_summary = {
            "status": (
                "paused_extended_hours"
                if phase in {"premarket", "afterhours"} and live_feed_available(now_et)
                else "extended_live_data_unavailable"
                if phase in {"premarket", "afterhours"}
                else "skipped_market_closed"
                if phase == "closed"
                else "unavailable"
            ),
            "validated": False,
            "version": "scanner-ml-v1",
            "target": ">= +3% at 60 minutes",
        }
        for row in rows:
            row["ml_status"] = ml_summary["status"]
            row["ml_validated"] = False
            row["ml_continuation_prob_pct"] = None
            row["opportunity_score"] = row.get("score")

    # Scanner ACTION stays on the simpler rule path. Advanced behavior context
    # is still calculated/logged for research, but replay validation must improve
    # before behavior-specific overrides are allowed to change production ACTION.
    assign_scanner_actions(rows, now_et)
    apply_scanner_data_integrity_gate(rows, now_et)

    if attach_timeframe_fit is not None:
        for row in rows:
            try:
                attach_timeframe_fit(row)
            except Exception as exc:
                row["timeframe_fit_error"] = str(exc)[:180]
                row["timeframe_best_fit"] = "UNKNOWN"

    # Timeframe Fit is display/logging intelligence only; the existing ranking
    # key remains untouched so this new layer cannot silently change production
    # momentum ordering.
    rows.sort(key=ranking_key, reverse=True)
    mark_stage("grading_and_ml")
    performance["total_before_logging"] = round(
        time.perf_counter() - scan_started,
        2,
    )

    print_watchlist(rows)
    print_catalysts(rows)
    print_setup_grades(rows, now_et)
    print_passers(rows)
    print_historical(rows)

    print("\nSCANNER ML")
    print(
        f"Status: {ml_summary.get('status')} | "
        f"validated={ml_summary.get('validated')} | "
        f"samples={ml_summary.get('samples', 0)} | "
        f"replay={ml_summary.get('historical_replay_samples', 0)} | "
        f"live={ml_summary.get('live_samples', 0)} | "
        f"days={ml_summary.get('trading_days', 0)} | "
        f"AUC={ml_summary.get('walk_forward_auc')}"
    )
    print(
        "Target: "
        + str(ml_summary.get("target") or ">= +3% at 60 minutes")
    )

    print("\nSCAN SUMMARY")
    print(f"Analyzed common-stock candidates: {len(rows)}")
    print(f"Passed every base filter: {sum(c['passed_base_filters'] for c in rows)}")
    grade_counts = Counter(c.get("setup_grade", "unknown") for c in rows)
    print(
        "Setup grades: "
        + ", ".join(f"{grade}={grade_counts.get(grade, 0)}" for grade in ["A", "B", "C", "REJECT"])
    )
    print(f"Likely warrants/rights/units excluded: {len(excluded_symbols)}")

    if excluded_symbols:
        print("Excluded symbols: " + ", ".join(excluded_symbols[:25]))

    if rejection_counts:
        print("Most common rejection reasons:")
        for reason, count in rejection_counts.most_common():
            print(f"  - {reason}: {count}")

    liquidity_counts = Counter(c.get("liquidity_source", "unknown") for c in rows)
    print("Liquidity source usage:")
    for source, count in liquidity_counts.most_common():
        print(f"  - {source}: {count}")

    warning_counts = Counter(
        warning
        for c in rows
        for warning in c.get("tradability_warnings", [])
    )
    if warning_counts:
        print("Most common IEX tradability warnings:")
        for warning, count in warning_counts.most_common():
            print(f"  - {warning}: {count}")

    print("\nPERFORMANCE")
    for stage_name, seconds in performance.items():
        print(f"{stage_name}: {seconds:.2f}s")

    write_scan_logs(
        rows,
        now_utc,
        now_et,
        excluded_symbols,
        ml_summary=ml_summary,
        performance=performance,
        discovery_meta=discovery_meta,
    )

    # The live Streamlit app scans much more frequently than the durable
    # GitHub Actions collector. When explicitly enabled by scanner_runtime,
    # inspect every live scan and preserve a bounded 15-minute-bucket journal
    # of the strongest/actionable states plus below-cutoff controls. This is
    # shadow learning data only and must never make the scan fail.
    if (
        os.environ.get("SCANNER_LIVE_JOURNAL_ENABLED", "").strip().lower()
        in {"1", "true", "yes", "on"}
    ):
        try:
            from scanner_live_journal import capture_live_scan

            journal = capture_live_scan(rows, now_et)
            print(
                "LIVE LEARNING JOURNAL | "
                f"captured={journal.get('captured', 0)} | "
                f"local={journal.get('local_count', 0)} | "
                f"remote={((journal.get('remote') or {}).get('reason') or ('synced' if (journal.get('remote') or {}).get('synced') else 'idle'))}"
            )
        except Exception as exc:
            print(f"WARN live learning journal failed: {exc}")

    print("\nJSON RESULTS - TOP WATCHLIST")
    # Console output is diagnostic only and must never turn a successfully
    # persisted scan into a failed workflow because a nested field contains a
    # datetime/date object.
    print(json.dumps(rows[:WATCHLIST_SIZE], indent=2, default=str))

scanner_discovery.py._num:
def _num(value):
    try:
        value = float(value)
        return value if math.isfinite(value) else None
    except Exception:
        return None

scanner_discovery.py._scale:
def _scale(value, start, end, points):
    value = _num(value)
    if value is None or end <= start:
        return 0.0
    return _clamp((value - start) / (end - start)) * points

scanner_discovery.py._pct_change:
def _pct_change(new, old):
    new = _num(new)
    old = _num(old)
    if new is None or old in (None, 0):
        return None
    return (new / old - 1.0) * 100.0

scanner_discovery.py._chunks:
def _chunks(values, size):
    for start in range(0, len(values), max(1, int(size))):
        yield values[start : start + max(1, int(size))]

scanner_discovery.py._load_public_symbols:
def _load_public_symbols(likely_common_stock):
    """Load the broad US-listed common-stock directory without broker auth."""
    sources = (
        (
            "https://www.nasdaqtrader.com/dynamic/SymDir/nasdaqlisted.txt",
            "nasdaqlisted",
        ),
        (
            "https://www.nasdaqtrader.com/dynamic/SymDir/otherlisted.txt",
            "otherlisted",
        ),
    )
    symbols = []
    seen = set()

    for url, kind in sources:
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "stock-scanner-full-market-radar/1.0"},
        )
        with urllib.request.urlopen(req, timeout=30) as response:
            text = response.read().decode("utf-8", errors="replace")
        lines = [line for line in text.splitlines() if "|" in line]
        if not lines:
            continue

        header = lines[0].split("|")
        index = {name: i for i, name in enumerate(header)}
        for line in lines[1:]:
            if line.startswith("File Creation Time"):
                continue
            fields = line.split("|")
            try:
                if kind == "nasdaqlisted":
                    symbol = fields[index["Symbol"]].strip().upper()
                    name = fields[index["Security Name"]].strip()
                    test_issue = fields[index["Test Issue"]].strip().upper()
                    etf = fields[index["ETF"]].strip().upper()
                else:
                    symbol = fields[index["ACT Symbol"]].strip().upper()
                    name = fields[index["Security Name"]].strip()
                    test_issue = fields[index["Test Issue"]].strip().upper()
                    etf = fields[index["ETF"]].strip().upper()
            except (KeyError, IndexError):
                continue

            if test_issue == "Y" or etf == "Y":
                continue
            if not symbol or symbol in seen:
                continue
            if not _security_name_looks_common(name):
                continue
            if not likely_common_stock(symbol):
                continue

            seen.add(symbol)
            symbols.append(symbol)

    if not symbols:
        raise RuntimeError("Public Nasdaq Trader directory returned no stock symbols.")
    return sorted(symbols)

scanner_discovery.py._read_universe_cache:
def _read_universe_cache(*, require_today=True):
    try:
        payload = json.loads(UNIVERSE_CACHE_PATH.read_text(encoding="utf-8"))
    except Exception:
        return None
    if int(payload.get("schema_version") or 0) != CACHE_SCHEMA_VERSION:
        return None
    if require_today and payload.get("market_date") != datetime.now(ET).date().isoformat():
        return None
    symbols = [
        str(symbol).upper().strip()
        for symbol in payload.get("symbols") or []
        if str(symbol).strip()
    ]
    return (symbols, payload) if len(symbols) >= 1000 else None

scanner_discovery.py._tradier_call:
def _tradier_call(fn, *args):
    delay = 1.0
    for attempt in range(5):
        try:
            return fn(*args)
        except urllib.error.HTTPError as exc:
            # Authentication/entitlement errors must surface immediately.
            if exc.code not in {429, 500, 502, 503, 504} or attempt >= 4:
                raise
        except urllib.error.URLError:
            if attempt >= 4:
                raise
        time.sleep(delay)
        delay = min(8.0, delay * 2.0)
    return None

scanner_discovery.py._timestamp_epoch:
def _timestamp_epoch(value):
    parsed = parse_market_timestamp(value)
    return parsed.timestamp() if parsed is not None else None

scanner_discovery.py._quote_midpoint:
def _quote_midpoint(row):
    bid = _num(row.get("bid"))
    ask = _num(row.get("ask"))
    if bid is None or ask is None or bid <= 0 or ask < bid:
        return None
    return (bid + ask) / 2.0

scanner_discovery.py._risk_lane:
def _risk_lane(price):
    price = _num(price) or 0.0
    if price < 1.0:
        return "SUB-$1"
    if price <= 50.0:
        return "$1-$50"
    return "ABOVE-$50"

scanner_discovery.py._load_state:
def _load_state():
    try:
        payload = json.loads(STATE_PATH.read_text(encoding="utf-8"))
    except Exception:
        return {}, False
    if int(payload.get("schema_version") or 0) != STATE_SCHEMA_VERSION:
        return {}, False
    observations = payload.get("observations")
    return (observations if isinstance(observations, dict) else {}), True

scanner_discovery.py._nearest_history:
def _nearest_history(history, now_ts, target_age):
    if not history:
        return None
    eligible = []
    for observation in history:
        observed_at = _num(observation.get("t"))
        if observed_at is None:
            continue
        age = now_ts - observed_at
        if age < max(20.0, target_age * 0.55):
            continue
        if age > max(target_age * 2.8, target_age + 240.0):
            continue
        eligible.append((abs(age - target_age), observation))
    if not eligible:
        return None
    eligible.sort(key=lambda item: item[0])
    return eligible[0][1]

scanner_discovery.py._tradeability_score:
def _tradeability_score(row):
    score = 0.0
    if row.get("radar_quote_fresh"):
        score += 25.0

    spread = _num(row.get("radar_spread_pct"))
    if spread is not None:
        if spread <= 0.5:
            score += 25.0
        elif spread <= 1.0:
            score += 22.0
        elif spread <= 2.0:
            score += 17.0
        elif spread <= 4.0:
            score += 10.0
        elif spread <= 8.0:
            score += 4.0

    dollar_volume = max(0.0, _num(row.get("discovery_dollar_volume")) or 0.0)
    score += _scale(math.log10(max(1.0, dollar_volume)), 4.5, 7.3, 25.0)

    rel_volume = max(0.0, _num(row.get("discovery_relative_volume")) or 0.0)
    score += _scale(rel_volume, 0.2, 4.0, 12.0)

    if row.get("radar_bid_ask_available"):
        score += 5.0

    lane = row.get("risk_lane")
    if lane == "$1-$50":
        score += 8.0
    elif lane == "ABOVE-$50":
        score += 6.0
    else:
        # Sub-dollar names remain discoverable but receive a deliberate
        # execution-risk haircut rather than a visibility ban.
        score += 2.0

    return round(max(0.0, min(100.0, score)), 1)

scanner_discovery.py._save_state:
def _save_state(rows, previous_state, now_ts):
    observations = {}
    for row in rows:
        symbol = row["symbol"]
        history = [
            item
            for item in previous_state.get(symbol, [])
            if _num(item.get("t")) is not None
            and 0 <= now_ts - float(item["t"]) <= STATE_RETENTION_SECONDS
        ]
        history.append(
            {
                "t": round(now_ts, 3),
                "p": row.get("discovery_price"),
                "v": row.get("discovery_volume") or 0.0,
            }
        )
        observations[symbol] = history[-STATE_POINTS_PER_SYMBOL:]

    payload = {
        "schema_version": STATE_SCHEMA_VERSION,
        "updated_at_utc": datetime.fromtimestamp(now_ts, tz=timezone.utc).isoformat(),
        "observations": observations,
    }
    _atomic_json_write(STATE_PATH, payload)

analyzer_v2_integration.py._num:
def _num(value):
    try:
        return float(value)
    except Exception:
        return None

analyzer_v2_integration.py._label:
def _label(score, high=72, moderate=52):
    if score >= high:
        return "HIGH"
    if score >= moderate:
        return "MODERATE"
    return "LOW"

analyzer_v2_integration.py._http_json:
def _http_json(url, timeout=6):
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": SEC_USER_AGENT,
            "Accept": "application/json",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))

analyzer_v2_integration.py._http_text:
def _http_text(url, timeout=6):
    req = urllib.request.Request(
        url,
        headers={
            "User-Agent": SEC_USER_AGENT,
            "Accept": "text/html,application/xhtml+xml",
        },
    )
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read().decode("utf-8", errors="ignore")

analyzer_v2_integration.py._ticker_map:
@lru_cache(maxsize=4)
def _ticker_map(bucket):
    payload = _http_json("https://www.sec.gov/files/company_tickers.json", timeout=8)
    out = {}
    for item in payload.values():
        ticker = str(item.get("ticker") or "").upper().strip()
        cik = item.get("cik_str")
        if ticker and cik is not None:
