            "timestamp":quote.get("t"),
            "source":f"{provider}_{feed}_quote_midpoint",
            "kind":"quote_midpoint",
        },
    ]

stock_analyzer.py._age_label:
def _age_label(dt_et, now):
    if dt_et is None:
        return "—"
    seconds = max(0, (now.astimezone(ET) - dt_et).total_seconds())
    minutes = int(seconds // 60)
    if minutes < 1:
        return "just now"
    if minutes < 60:
        return f"{minutes}m ago"
    hours = minutes // 60
    if hours < 24:
        rem = minutes % 60
        return f"{hours}h {rem}m ago" if rem else f"{hours}h ago"
    days = hours // 24
    rem_hours = hours % 24
    return f"{days}d {rem_hours}h ago" if rem_hours else f"{days}d ago"

stock_analyzer.py._touch_time_label:
def _touch_time_label(dt_et):
    if dt_et is None:
        return "—"
    clock = dt_et.strftime("%I:%M %p").lstrip("0")
    return f"{dt_et.strftime('%b')} {dt_et.day}, {clock} ET"

stock_analyzer.py.avg_daily_volume:
def avg_daily_volume(symbol, now, daily_bars=None, source=None):
    if daily_bars is None:
        bs,src=try_sip_delayed_bars(symbol,"1Day",now-timedelta(days=50),now,50)
    else:
        bs=list(daily_bars or [])
        src=source or "shared daily history"
    today=now.astimezone(ET).date().isoformat()
    vals=[fnum(b.get("v")) for b in bs if str(b.get("t",""))[:10]!=today and fnum(b.get("v"))]
    vals=vals[-20:]
    return (sum(vals)/len(vals) if vals else None),src

stock_analyzer.py.pivot_levels:
def pivot_levels(daily_bars, current):
    levels=[]
    for b in daily_bars[-45:]:
        for kind,key in (("high","h"),("low","l"),("close","c")):
            v=fnum(b.get(key))
            if v and v>0: levels.append((v,kind,str(b.get("t",""))[:10]))
    # Cluster nearby levels within ~2.2%.
    levels.sort()
    clusters=[]
    for lv in levels:
        if not clusters or abs(lv[0]/clusters[-1][0][0]-1)>.022: clusters.append([lv])
        else: clusters[-1].append(lv)
    scored=[]
    for c in clusters:
        price=median([x[0] for x in c]); touches=len(c)
        scored.append({"price":round(price,2),"touches":touches,"side":"support" if price<current else "resistance"})
    supports=sorted([x for x in scored if x["side"]=="support"],key=lambda x:current-x["price"])[:4]
    resist=sorted([x for x in scored if x["side"]=="resistance"],key=lambda x:x["price"]-current)[:4]
    return supports,resist

stock_analyzer.py.atr_from_daily:
def atr_from_daily(daily_bars, now, periods=14):
    """Completed-session ATR and ATR% using true range."""
    if not daily_bars:
        return None, None
    today=now.astimezone(ET).date().isoformat()
    completed=[b for b in daily_bars if str(b.get("t", ""))[:10] != today]
    if len(completed) < 3:
        return None, None
    trs=[]
    for i in range(1, len(completed)):
        h=fnum(completed[i].get("h")); l=fnum(completed[i].get("l")); pc=fnum(completed[i-1].get("c"))
        if h is None or l is None or pc is None or pc <= 0:
            continue
        trs.append(max(h-l, abs(h-pc), abs(l-pc)))
    if not trs:
        return None, None
    atr=sum(trs[-periods:])/len(trs[-periods:])
    last_close=fnum(completed[-1].get("c"))
    return atr, (atr/last_close*100 if last_close else None)

stock_analyzer.py._level_age_hours:
def _level_age_hours(level, now):
    raw=level.get("last_touch")
    if not raw:
        return None
    try:
        dt=datetime.fromisoformat(str(raw))
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=ET)
        return max(0.0, (now-dt.astimezone(timezone.utc)).total_seconds()/3600)
    except Exception:
        return None

stock_analyzer.py._nearest_level:
def _nearest_level(levels, price, direction):
    vals=[]
    for level in levels or []:
        p=fnum(level.get("price"))
        if not p: continue
        if direction == "below" and p < price:
            vals.append(level)
        elif direction == "above" and p > price:
            vals.append(level)
    if not vals:return None
    return min(vals,key=lambda x:abs((fnum(x.get("price")) or price)-price))

stock_analyzer.py._next_resistance:
def _next_resistance(resistances, above_price):
    vals=[x for x in (resistances or []) if (fnum(x.get("price")) or 0) > above_price]
    return min(vals,key=lambda x:fnum(x.get("price"))) if vals else None

stock_analyzer.py._price_zone:
def _price_zone(center, half_width_pct):
    if not center:return None
    return {
        "low":round(center*(1-half_width_pct/100),4),
        "high":round(center*(1+half_width_pct/100),4),
    }

stock_analyzer.py._hist_trade_context:
def _hist_trade_context(hist):
    out={"sample_count":0,"next_day_up_pct":None,"median_close_1d":None,"median_mfe_1d":None,"median_mfe_3d":None,"median_mae_1d":None,"median_mae_3d":None}
    if not hist or hist.get("status") != "ok":return out
    out["sample_count"]=int(hist.get("sample_count") or 0)
    d1=(hist.get("summary") or {}).get("d1") or {}
    d3=(hist.get("summary") or {}).get("d3") or {}
    out.update({
        "next_day_up_pct":d1.get("up_pct"),
        "median_close_1d":d1.get("median"),
        "median_mfe_1d":d1.get("median_mfe"),
        "median_mfe_3d":d3.get("median_mfe"),
        "median_mae_1d":d1.get("median_mae"),
        "median_mae_3d":d3.get("median_mae"),
    })
    return out

stock_analyzer.py._catalyst_bias:
def _catalyst_bias(news_rows):
    if not news_rows:return {"label":"NEUTRAL","score":0,"headline":None}
    weighted=[]
    for a in news_rows:
        raw=float(a.get("score") or 0)
        age=a.get("age_hours")
        decay=1.0 if age is None else max(0.25, 1-(float(age)/120))
        weighted.append((raw*decay,a))
    val,a=max(weighted,key=lambda x:abs(x[0]))
    return {
        "label":"POSITIVE" if val>=3 else "NEGATIVE" if val<=-3 else "NEUTRAL",
        "score":round(val,1),
        "headline":a.get("headline") if a else None,
    }

stock_analyzer.py.score_setup:
def score_setup(metrics):
    score=50.0; reasons=[]
    p=metrics.get("price") or 0; vwap=metrics.get("vwap")
    if vwap:
        ext=pct(p,vwap)
        if ext>=0: score+=8; reasons.append("above VWAP")
        else: score-=8; reasons.append("below VWAP")
        if ext>20: score-=16; reasons.append("severely extended >20% above VWAP")
        elif ext>12: score-=10; reasons.append("extended >12% above VWAP")
    m5=metrics.get("momentum_5m")
    m15=metrics.get("momentum_15m")
    if m5 is not None: score+=max(-8,min(8,m5*2))
    if m15 is not None: score+=max(-8,min(8,m15))
    fp=metrics.get("from_high_pct")
    if fp is not None:
        if fp<=3:score+=8
        elif fp>=15:score-=8; reasons.append("far below day high")
    sequence=metrics.get("bounce_sequence") or {}
    seq_health=fnum(sequence.get("sequence_health_score"))
    seq_decay=fnum(sequence.get("bounce_decay_ratio"))
    if seq_health is not None:
        if seq_health>=68:score+=5; reasons.append("healthy multi-bounce structure")
        elif seq_health<42:score-=9; reasons.append("multi-bounce sequence is decaying")
    if int(sequence.get("lower_high_streak") or 0)>=2:
        score-=7; reasons.append("repeated lower highs across bounces")
    if seq_decay is not None and seq_decay<0.65:
        score-=5; reasons.append("latest bounce is materially weaker than the prior bounce")
    stair=metrics.get("stair_step") or {}
    stair_score=fnum(stair.get("structure_score"))
    if stair.get("reaccelerating") and stair_score is not None and stair_score>=65:
        score+=7; reasons.append("multi-session stair-step is reaccelerating")
    elif stair.get("state")=="HIGHER PLATEAU / COILING" and stair_score is not None and stair_score>=58:
        score+=4; reasons.append("price is holding a higher multi-session plateau")
    if stair.get("breakdown"):
        score-=10; reasons.append("latest stair-step plateau has broken down")
    exhaustion=metrics.get("run_exhaustion") or {}
    ex_score=fnum(exhaustion.get("score"))
    if ex_score is not None:
        if ex_score>=78:score-=18; reasons.append("very high run-exhaustion / reversal risk")
        elif ex_score>=62:score-=10; reasons.append("elevated run-exhaustion risk")
        elif ex_score>=42:score-=4
    pace=metrics.get("volume_pace")
    if pace is not None:
        if pace>=2:score+=10; reasons.append("strong relative volume")
        elif pace<0.7:score-=5
    spread=metrics.get("spread_pct")
    if spread is not None:
        if spread<1:score+=4
        elif spread>5:score-=7; reasons.append("wide live spread")
    day=metrics.get("day_pct") or 0
    chase=max(0, day-25)*0.16 + max(0,(pct(p,vwap) if vwap else 0)-5)*0.5
    score-=min(18,chase)
    score=max(0,min(100,score))
    grade="A" if score>=78 else "B" if score>=65 else "C" if score>=52 else "REJECT"
    entry="FAVORABLE" if score>=72 and chase<10 else "WAIT / CONFIRM" if score>=55 else "POOR / HIGH RISK"
    return round(score,1),grade,entry,reasons

scanner_ranking.py.tradeability_value:
def tradeability_value(row):
    """Return a finite score, or None when no usable score was published."""
    value = row.get("tradeability_score")
    if isinstance(value, bool):
        return None
    try:
        score = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return score if math.isfinite(score) else None

scanner_ranking.py.rank_candidates:
def rank_candidates(records):
    """Return a sorted view without mutating source rows or publication order."""
    return sorted(records, key=tradeability_rank_key, reverse=True)

protected.analyzer_wrapper:
def install_v2_analysis(sa):
    """Add separate upside-potential, entry-timing and evidence scores."""
    if hasattr(sa, '_decision_v2_analyze'):
        return sa._decision_v2_analyze
    base_analyze = sa.analyze

    def enhanced_analyze(symbol):
        symbol_clean = str(symbol or '').upper().strip()
        sip_status = prefer_best_live_feed(sa, 'SPY')
        metrics = base_analyze(symbol)
        now = datetime.now(timezone.utc)
        live_data_integrity = _analyzer_live_data_integrity(metrics)
        research_only = bool(metrics.get('research_only'))
        if research_only:
            thesis_context = {'status': 'RESEARCH ONLY', 'change_reason': 'The market is closed; completed-session research cannot create or modify a live execution thesis.', 'committed': False}
        else:
            thesis_context = prepare_intraday_thesis(metrics, now=now, evidence_trusted=bool(live_data_integrity.get('ok')), persist=False)
        background_worker = os.environ.get('ANALYZER_BACKGROUND_WORKER', '').strip() == '1'
        if research_only:
            stream_status = {'status': 'research_only', 'provider': 'completed_session_history', 'feed': metrics.get('historical_feed'), 'background_worker': background_worker}
            live_overlay = {}
        elif background_worker:
            stream_status = {'status': 'snapshot_only', 'provider': metrics.get('live_provider'), 'feed': metrics.get('live_feed'), 'background_worker': True}
            live_overlay = {}
        else:
            stream_status = ensure_live_stream(symbol_clean, str(sa.LIVE_FEED or 'iex').lower(), metrics=metrics)
            live_overlay = get_live_overlay(metrics)
        with ThreadPoolExecutor(max_workers=2) as _slow_pool:
            _sec_future = _slow_pool.submit(_recent_sec_risk, symbol_clean)
            _float_future = _slow_pool.submit(get_public_float, symbol_clean)
            sec = _sec_future.result()
            float_context = _float_future.result()
        market = _market_context(sa, sec.get('sector_etf'))
        catalyst = _catalyst_strength(metrics.get('news') or [])
        turnover = _turnover_context(metrics, sec, float_context)
        potential, potential_reasons, potential_components = _potential_score(metrics, sec, market, catalyst)
        readiness, blockers, entry_components = _entry_readiness(metrics)
        if research_only:
            readiness = 0.0
            blockers = ['LIVE ENTRY TIMING DISABLED — market closed', 'Recheck when a fresh symbol-matched quote is available.']
            entry_components = {'base': 0.0}
        evidence, evidence_reasons = _evidence_strength(metrics, sec, market, catalyst)
        timeframe = _timeframe_analysis(sa, symbol_clean, metrics, sec, market, catalyst, potential, readiness)
        raw_best_fit = timeframe.get('best_fit')
        horizon_continuity = track_timeframe_thesis(symbol_clean, timeframe, now=now, persist=False)
        timeframe['raw_best_fit'] = raw_best_fit
        timeframe['stable_best_fit'] = horizon_continuity.get('stable_best_fit') or raw_best_fit
        timeframe['continuity'] = horizon_continuity
        timeframe['production_influence'] = False
        timeframe['research_only'] = research_only
        swing_research = evaluate_swing_research_flags(metrics, timeframe)
        timeframe['swing_research_flags'] = swing_research
        metrics['decision_v2'] = {'potential_score': potential}
        full_spectrum = _full_spectrum_analysis(metrics, sec, market, catalyst, turnover)
        plan = metrics.get('trade_plan') or {}
        if str(plan.get('status') or '') == 'ENTRY AVAILABLE':
            safety_reasons = []
            if not live_data_integrity.get('ok'):
                safety_reasons.append('live-data integrity check failed: ' + '; '.join((live_data_integrity.get('reasons') or [])[:3]))
            if readiness < 60:
                safety_reasons.append('entry readiness is below 60/100')
            if evidence < 50:
                safety_reasons.append('evidence strength is below 50/100')
            reversal_risk = _num(full_spectrum.get('reversal_risk_score'))
            preferred_plan = str(plan.get('preferred_plan') or '')
            reversal_cap = 78 if preferred_plan == 'repeat_bounce' else 68
            if reversal_risk is not None and reversal_risk >= reversal_cap:
                safety_reasons.append('run-exhaustion / reversal risk is very high for the later-bounce scalp' if preferred_plan == 'repeat_bounce' else 'run-exhaustion / reversal risk is high')
            if safety_reasons:
                plan['status'] = 'WAIT'
                plan['action'] = 'WAIT FOR STRONGER CONFIRMATION'
                selected_plan = plan.get('selected') or {}
                entry_low = _num(selected_plan.get('entry_low'))
                entry_high = _num(selected_plan.get('entry_high'))
                if entry_low is not None and entry_high is not None:
                    entry_zone_text = f'${entry_low:.2f}–${entry_high:.2f}'
                else:
                    entry_zone_text = 'the displayed entry zone'
                if not live_data_integrity.get('ok'):
                    plan['entry_state'] = 'DATA CHECK'
                    plan['entry_instruction'] = f'NO ENTRY SIGNAL while live data is stale, incomplete, or not trusted. {entry_zone_text} remains a watch area only; wait for fresh consolidated price/quote plus the required momentum inputs.'
                else:
                    plan['entry_state'] = 'WAIT FOR CONFIRMATION'
                    plan['entry_instruction'] = f'NEXT ENTRY remains {entry_zone_text}, but it is NOT actionable yet. Wait until the readiness/evidence/reversal gates clear; do not treat a zone touch as an entry.'
                plan_reasons = list(plan.get('reasons') or [])
                plan_reasons.insert(0, 'Entry withheld because ' + ' and '.join(safety_reasons) + '.')
                plan['reasons'] = plan_reasons
                metrics['trade_plan'] = plan
                blockers = ['WAIT FOR STRONGER CONFIRMATION'] + list(blockers)
                old_readiness = readiness
                readiness = min(readiness, 59.0)
                if old_readiness != readiness:
                    entry_components['evidence_safety_cap'] = round(readiness - old_readiness, 1)
        decision_contract = _finalize_trade_plan_contract(metrics, live_data_integrity=live_data_integrity)
        plan = metrics.get('trade_plan') or {}
        thesis_context = plan.get('thesis_continuity') or thesis_context
        metrics['decision_v2'] = {'version': DECISION_SCORE_VERSION, 'potential_score': potential, 'potential_label': _label(potential, 72, 52), 'entry_readiness': readiness, 'entry_label': 'UNAVAILABLE' if research_only else _label(readiness, 72, 52), 'evidence_strength': evidence, 'evidence_label': _label(evidence, 72, 52), 'potential_reasons': potential_reasons, 'potential_components': potential_components, 'entry_blockers': blockers, 'entry_components': entry_components, 'evidence_reasons': evidence_reasons, 'catalyst_strength': catalyst, 'market_context': market, 'fundamental_context': sec, 'float_context': float_context, 'turnover_context': turnover, 'live_data_integrity': live_data_integrity, 'decision_contract': decision_contract, 'thesis_continuity': thesis_context, 'timeframe_analysis': timeframe, 'full_spectrum': full_spectrum, 'sip_status': sip_status, 'live_stream_status': stream_status, 'live_overlay': live_overlay}
        if not research_only:
            commit_intraday_thesis(metrics, thesis_context, now=now)
            commit_timeframe_thesis(horizon_continuity)
        plan = metrics.get('trade_plan') or {}
        thesis_context = plan.get('thesis_continuity') or thesis_context
        metrics['decision_v2']['thesis_continuity'] = thesis_context
        if background_worker:
            try:
                record_result = record_prediction(metrics, now, defer_remote=True)
                tracking = {'status': 'recorded_local_sync_deferred', 'persistence': 'github+local (async sync deferred)' if durable_tracking_enabled() else 'runtime-local', 'durable_enabled': durable_tracking_enabled(), 'background_worker': True, 'last_record': record_result}
            except Exception as exc:
                tracking = {'status': 'record_failed', 'error': str(exc)[:140], 'background_worker': True}
        else:
            try:
                record_result = record_prediction(metrics, now)
                tracking = resolve_symbol_predictions(sa, symbol_clean, now, current_metrics=metrics)
                tracking['last_record'] = record_result
            except Exception as exc:
                tracking = {'error': str(exc)[:140], 'persistence': 'runtime-local'}
        metrics['decision_v2']['tracking'] = tracking
        return metrics
    sa._decision_v2_analyze = enhanced_analyze
    sa.analyze = enhanced_analyze
    return enhanced_analyze
